"""Referencia independente Pandas sobre o export real, sem executar Fabric."""
import argparse,json,hashlib,sys
from pathlib import Path
from decimal import Decimal
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
import pandas as pd
from fuelwatch.analytics import decimal_median,relative_difference,row_hash

parser=argparse.ArgumentParser();parser.add_argument('--history',action='store_true');args=parser.parse_args()
out=ROOT/('data/artifacts/analytics-history' if args.history else 'data/artifacts/analytics');out.mkdir(exist_ok=True,parents=True)
if args.history:
 f=pd.read_parquet(ROOT/'data/artifacts/history/publication/reference.parquet')
 dates=pd.to_datetime(f.data_coleta);f['inicio_semana_iso']=(dates-pd.to_timedelta(dates.dt.dayofweek,unit='d')).dt.date
 municipalities=pd.read_parquet(ROOT/'data/artifacts/national/municipalities.parquet',columns=['municipio_ibge','nome']).rename(columns={'nome':'municipio_ibge_nome'})
 n=len(f);f=f.merge(municipalities,on='municipio_ibge',how='left',validate='many_to_one');assert len(f)==n and f.municipio_ibge_nome.notna().all()
else:f=pd.read_parquet(ROOT/'data/processed/anp_brasil_2026_1.parquet')
f['mills']=f.preco_venda.map(lambda p:int(p*1000))
key=['cnpj','produto','moeda','unidade','inicio_semana_iso'];region=['uf','produto','moeda','unidade','inicio_semana_iso'];city=['municipio_ibge','produto','moeda','unidade','inicio_semana_iso']
f=f.sort_values('data_coleta');g=f.groupby(key,dropna=False);last=g.tail(1).set_index(key);agg=g.agg(mills=('mills','median'),coletas=('cnpj','size'),soma_mills=('mills','sum'),ufs=('uf','nunique'),municipios=('municipio_ibge','nunique'),bandeiras=('bandeira_observada','nunique'))
p=last[['uf','municipio_ibge','municipio_ibge_nome','bandeira_observada','revenda_observada']].join(agg).reset_index();p['preco_mediano']=p.mills.map(lambda x:Decimal(str(x))/1000);p['soma_precos']=p.soma_mills.map(lambda x:Decimal(int(x))/1000);p['comparacao_valida']=(p.ufs==1)&(p.municipios==1)&(p.bandeiras==1);p=p[key+['uf','municipio_ibge','municipio_ibge_nome','bandeira_observada','revenda_observada','preco_mediano','coletas','soma_precos','comparacao_valida']]
valid=p[p.comparacao_valida];r=valid.groupby(region).agg(postos_referencia=('cnpj','size'),mediana_uf=('preco_mediano',decimal_median)).reset_index();positions=p.merge(r,on=region,how='left',validate='many_to_one');positions['benchmark_elegivel']=positions.comparacao_valida&(positions.postos_referencia>=10);positions['diferenca_uf']=[v-b if e else None for v,b,e in zip(positions.preco_mediano,positions.mediana_uf,positions.benchmark_elegivel)];positions['desvio_percentual']=[relative_difference(v,b,e) for v,b,e in zip(positions.preco_mediano,positions.mediana_uf,positions.benchmark_elegivel)];positions['posicao']=['atributo_ambiguo' if not valid else 'cobertura_insuficiente' if not e else 'acima' if d>0 else 'abaixo' if d<0 else 'igual' for valid,e,d in zip(positions.comparacao_valida,positions.benchmark_elegivel,positions.diferenca_uf)]
municipal=valid.groupby(['uf','municipio_ibge','municipio_ibge_nome','produto','moeda','unidade','inicio_semana_iso']).agg(postos_municipio=('cnpj','size'),mediana_municipio=('preco_mediano',decimal_median)).reset_index().merge(r,on=region,validate='many_to_one');municipal['benchmark_elegivel']=(municipal.postos_municipio>=3)&(municipal.postos_referencia>=10);municipal['diferenca_uf']=[a-b if e else None for a,b,e in zip(municipal.mediana_municipio,municipal.mediana_uf,municipal.benchmark_elegivel)]
positions['above']=positions.posicao=='acima';persist=positions.groupby(['cnpj','uf','produto','moeda','unidade']).agg(semanas_observadas=('cnpj','size'),semanas_com_benchmark=('benchmark_elegivel','sum'),semanas_acima=('above','sum')).reset_index();persist['persistencia_percentual']=[(Decimal(int(a))*100/Decimal(int(n))).quantize(Decimal('.000001')) if n>=4 else None for a,n in zip(persist.semanas_acima,persist.semanas_com_benchmark)];positions=positions.drop(columns='above')
bands=valid.groupby(['uf',*city,'bandeira_observada']).agg(postos_bandeira=('cnpj','size'),mediana_bandeira=('preco_mediano',decimal_median)).reset_index();bands=bands[bands.postos_bandeira>=2].copy();bands['bandeiras_contexto']=bands.groupby(city).bandeira_observada.transform('size');bands=bands[bands.bandeiras_contexto>=2].merge(municipal[city+['postos_municipio','mediana_municipio']],on=city,validate='many_to_one');bands=bands[bands.postos_municipio>=3];bands['diferenca_contexto']=bands.mediana_bandeira-bands.mediana_municipio
comparison=bands.groupby(['uf','produto','moeda','unidade','bandeira_observada']).agg(contextos_comparaveis=('municipio_ibge','size'),diferenca_mediana_contextual=('diferenca_contexto',decimal_median)).reset_index()
tables={'posto_semana':p,'referencia_uf_semana':r,'posicao_posto_semana':positions,'municipio_semana':municipal,'persistencia_posto':persist,'bandeira_contexto':bands,'comparacao_bandeira':comparison};manifest={}
intcols={'coletas','postos_referencia','postos_municipio','semanas_observadas','semanas_com_benchmark','semanas_acima','postos_bandeira','bandeiras_contexto','contextos_comparaveis'};boolcols={'comparacao_valida','benchmark_elegivel'};deccols={'preco_mediano','soma_precos','mediana_uf','diferenca_uf','desvio_percentual','mediana_municipio','persistencia_percentual','mediana_bandeira','diferenca_contexto','diferenca_mediana_contextual'}
for name,t in tables.items():
 kinds=['decimal' if x in deccols else 'int' if x in intcols else 'bool' if x in boolcols else 'date' if x=='inicio_semana_iso' else 'str' for x in t.columns];hashes=sorted(row_hash(row,kinds) for row in t.itertuples(index=False,name=None));(out/(name+'-row-hashes.txt')).write_text('\n'.join(hashes));manifest[name]={'rows':len(t),'columns':t.columns.tolist(),'kinds':kinds,'business_sha256':hashlib.sha256('\n'.join(hashes).encode()).hexdigest()};t.to_parquet(out/(name+'.parquet'),index=False)
(out/'reference.json').write_text(json.dumps(manifest,indent=2));print(json.dumps({k:v['rows'] for k,v in manifest.items()}),flush=True)
